import{_ as e,o as r,c as p,a2 as o}from"./chunks/framework.BdWD-ld-.js";const u=JSON.parse('{"title":"2026-11-19 Agent 核心研究与竞品动态","description":"","frontmatter":{"title":"2026-11-19 Agent 核心研究与竞品动态","outline":[2,3]},"headers":[],"relativePath":"zh/runtime/daily-intelligence/2026-11-19.md","filePath":"zh/runtime/daily-intelligence/2026-11-19.md","lastUpdated":null}'),t={name:"zh/runtime/daily-intelligence/2026-11-19.md"};function l(h,a,n,i,s,c){return r(),p("div",null,[...a[0]||(a[0]=[o('<h1 id="_2026-11-19-agent-核心研究与竞品动态" tabindex="-1">2026-11-19 Agent 核心研究与竞品动态 <a class="header-anchor" href="#_2026-11-19-agent-核心研究与竞品动态" aria-label="Permalink to &quot;2026-11-19 Agent 核心研究与竞品动态&quot;">​</a></h1><p>本轮核心判断：企业化治理需要把技能声明、具体身份与对象版本、实际执行和外部交付证据接起来。最值得学习的是 Bulbasaur 的技能契约与显式评测、Codex 的子会话授权边界、Paperclip 的交付门槛及 Orca 的跨端状态权威。</p><p>实际起点：2026-11-19 10:47:09 Asia/Shanghai。最新 main Registry 为47人，88个原始仓库入口；接续 2026-11-18T020523Z 检查记录与已发布日档去重，无补造历史日报。下文发生日期为UTC。57项观察、7组分析；实验、文章、正式开发评审和外部评论均为0。合入、发行、实验开关与生产可用分别判断。</p><h2 id="事实观察" tabindex="-1">事实观察 <a class="header-anchor" href="#事实观察" aria-label="Permalink to &quot;事实观察&quot;">​</a></h2><p><span id="o1"></span></p><h3 id="o1-mansura-habiba-技能副作用声明开始约束权限" tabindex="-1">O1 Mansura Habiba：技能副作用声明开始约束权限 <a class="header-anchor" href="#o1-mansura-habiba-技能副作用声明开始约束权限" aria-label="Permalink to &quot;O1 Mansura Habiba：技能副作用声明开始约束权限&quot;">​</a></h3><p>11月18日 #25 已合入。用同一操作成本表交叉检查 permissions 与 risk.side_effects，并由 SideEffectCeiling / PermissionsHook 拒绝超限操作、记录追加式审计。正则限定命令仍只是未验证的只读判断；完整 hook bus 不在本次范围。作者本人提交，项目是 AGENTSAFE 相关研究入口，不能标为其官方 Artifact。</p><p>原始证据与状态：<a href="https://github.com/mansura-habiba/bulbasaur-skill-cli/pull/25" target="_blank" rel="noreferrer">MERGED · 2026-11-18T15:07:59Z</a></p><p>研究追溯：<a href="#a1">A1</a></p><p><span id="o2"></span></p><h3 id="o2-bulbasaur-静态技能评估成为独立-rest-mcp-服务" tabindex="-1">O2 Bulbasaur：静态技能评估成为独立 REST/MCP 服务 <a class="header-anchor" href="#o2-bulbasaur-静态技能评估成为独立-rest-mcp-服务" aria-label="Permalink to &quot;O2 Bulbasaur：静态技能评估成为独立 REST/MCP 服务&quot;">​</a></h3><p>11月18日 #26 已合入。新增独立 api/ 包，REST validate/assess 与 MCP 工具调用同一静态编译评估服务，回执含精确 SKILL.md 字节的 SHA-256。默认行为评测为 not_run；OAC 适配仅只读 mock 和候选 schema，没有 Catalog 批准或上游集成完成。REST 有独立 bearer token，MCP 限 loopback；仓库 License 已核验为 Apache-2.0。可按 api/README 的 uv 步骤运行，本轮未安装。</p><p>原始证据与状态：<a href="https://github.com/mansura-habiba/bulbasaur-skill-cli/pull/26" target="_blank" rel="noreferrer">MERGED · 2026-11-18T12:55:26Z</a></p><p>研究追溯：<a href="#a1">A1</a></p><p><span id="o3"></span></p><h3 id="o3-bulbasaur-行为评测必须显式启用-mock-不代表技能有效" tabindex="-1">O3 Bulbasaur：行为评测必须显式启用，mock 不代表技能有效 <a class="header-anchor" href="#o3-bulbasaur-行为评测必须显式启用-mock-不代表技能有效" aria-label="Permalink to &quot;O3 Bulbasaur：行为评测必须显式启用，mock 不代表技能有效&quot;">​</a></h3><p>11月18日 #29 已合入。REST/MCP assess 可接收 evaluation，服务端控制 runtime allowlist 和案例数量，显式运行返回 v2 证据，默认保留静态 v1。默认 mock runtime/heuristic judge 只验证评测管线；Ollama 必须由操作员启用，仍无硬隔离和硬超时，仅开发使用。未执行技能脚本，未接入 Pi/Gantry；PR 正文旧 draft 提示不改变 API 已合入状态。</p><p>原始证据与状态：<a href="https://github.com/mansura-habiba/bulbasaur-skill-cli/pull/29" target="_blank" rel="noreferrer">MERGED · 2026-11-18T13:40:45Z</a></p><p>研究追溯：<a href="#a1">A1</a></p><p><span id="o4"></span></p><h3 id="o4-mcp-typescript-sdk-扩展与请求中间件合入-接口仍实验性" tabindex="-1">O4 MCP TypeScript SDK：扩展与请求中间件合入，接口仍实验性 <a class="header-anchor" href="#o4-mcp-typescript-sdk-扩展与请求中间件合入-接口仍实验性" aria-label="Permalink to &quot;O4 MCP TypeScript SDK：扩展与请求中间件合入，接口仍实验性&quot;">​</a></h3><p>11月18日 #2820 已合入。客户端/服务端扩展使用 id + setup(ctx)，可声明依赖、注册自有请求、包裹接收的请求；重复 ID、缺依赖或覆盖已有方法会失败。扩展中间件先于后加的应用中间件。当前不覆盖 notification 和出站中间件，底层 Server 不变；标记 experimental，可能随小版本调整，不能当成新的正式协议发布。</p><p>原始证据与状态：<a href="https://github.com/modelcontextprotocol/typescript-sdk/pull/2820" target="_blank" rel="noreferrer">MERGED · 2026-11-18T16:47:53Z</a></p><p>研究追溯：<a href="#a1">A1</a> · <a href="#a6">A6</a></p><p><span id="o5"></span></p><h3 id="o5-mcp-sdk-结构化结果可回填文本-保留显式空内容语义" tabindex="-1">O5 MCP SDK：结构化结果可回填文本，保留显式空内容语义 <a class="header-anchor" href="#o5-mcp-sdk-结构化结果可回填文本-保留显式空内容语义" aria-label="Permalink to &quot;O5 MCP SDK：结构化结果可回填文本，保留显式空内容语义&quot;">​</a></h3><p>11月18日 #3153 已合入。structuredContent 存在而 content 缺失时生成 JSON 文本块，兼容只读 content 的客户端；显式给出 content:[] 不回填。携带其他结果族字段的无 content 结果仍被拒绝；所述新 conformance 场景尚未进入已发行测试集。</p><p>原始证据与状态：<a href="https://github.com/modelcontextprotocol/typescript-sdk/pull/3153" target="_blank" rel="noreferrer">MERGED · 2026-11-18T17:31:45Z</a></p><p>研究追溯：<a href="#a1">A1</a> · <a href="#a6">A6</a></p><p><span id="o6"></span></p><h3 id="o6-mcp-sdk-库自身日志可注入-避免污染-stdio-协议" tabindex="-1">O6 MCP SDK：库自身日志可注入，避免污染 stdio 协议 <a class="header-anchor" href="#o6-mcp-sdk-库自身日志可注入-避免污染-stdio-协议" aria-label="Permalink to &quot;O6 MCP SDK：库自身日志可注入，避免污染 stdio 协议&quot;">​</a></h3><p>11月18日 #2370 已合入。Client、McpServer、HTTP handler 和 OAuth provider 可指定 SDK logger，把诊断与 JSON-RPC stdout 分开；OAuth 自定义提供方使用 sdkLogger。日志器抛错会被忽略，缺省仍沿用 console。它提供可观测接入点，本身不提供脱敏与过滤策略。</p><p>原始证据与状态：<a href="https://github.com/modelcontextprotocol/typescript-sdk/pull/2370" target="_blank" rel="noreferrer">MERGED · 2026-11-18T16:20:09Z</a></p><p>研究追溯：<a href="#a1">A1</a> · <a href="#a6">A6</a></p><p><span id="o7"></span></p><h3 id="o7-github-mcp-server-pr-工件工具采用双重开放边界" tabindex="-1">O7 GitHub MCP Server：PR 工件工具采用双重开放边界 <a class="header-anchor" href="#o7-github-mcp-server-pr-工件工具采用双重开放边界" aria-label="Permalink to &quot;O7 GitHub MCP Server：PR 工件工具采用双重开放边界&quot;">​</a></h3><p>11月18日 #3843 已合入，实验性 list/upsert/delete PR artifacts 工具默认关闭。客户端开启 MCP feature 仍需目标仓库通过 GitHub 独立 API rollout gate；只读模式不暴露写工具，lockdown 拒绝操作。上游做过测试仓库操作，未测试 rollout 开关对照，细粒度权限映射也未独立核验。</p><p>原始证据与状态：<a href="https://github.com/github/github-mcp-server/pull/3843" target="_blank" rel="noreferrer">MERGED · 2026-11-18T15:33:22Z</a></p><p>研究追溯：<a href="#a6">A6</a></p><p><span id="o8"></span></p><h3 id="o8-github-cli-事件等待有可运行命令-但仍需预览资格" tabindex="-1">O8 GitHub CLI：事件等待有可运行命令，但仍需预览资格 <a class="header-anchor" href="#o8-github-cli-事件等待有可运行命令-但仍需预览资格" aria-label="Permalink to &quot;O8 GitHub CLI：事件等待有可运行命令，但仍需预览资格&quot;">​</a></h3><p>11月18日官方发布 gh 2.105.0 的 gh event listen：创建订阅、输出 JSON 行，默认首个事件后退出，可配置 count/follow/timeout，覆盖 PR 评审、head/状态变化和完成检查。命令及 Event Streams 仍预览，需要候补资格；这是昨日事件流公告之后的 CLI 接入新增，尚未证明重放或 exactly-once。</p><p>原始证据与状态：<a href="https://github.blog/changelog/2026-11-18-wait-for-pull-request-events-with-github-cli/" target="_blank" rel="noreferrer">OFFICIAL_ANNOUNCEMENT · 2026-11-18</a></p><p>研究追溯：<a href="#a6">A6</a></p><p><span id="o9"></span></p><h3 id="o9-copilot-团队插件默认配置-ga-组织策略保持上位" tabindex="-1">O9 Copilot：团队插件默认配置 GA，组织策略保持上位 <a class="header-anchor" href="#o9-copilot-团队插件默认配置-ga-组织策略保持上位" aria-label="Permalink to &quot;O9 Copilot：团队插件默认配置 GA，组织策略保持上位&quot;">​</a></h3><p>11月18日官方宣布团队定制 GA，适用于 Business/Enterprise。维护者和组织所有者为直接成员选择默认插件；子团队不继承，策略允许时成员可关闭。企业/组织要求或阻止的插件和市场仍优先。学习价值高，岗位能力分发与企业配置竞争关注提高。</p><p>原始证据与状态：<a href="https://github.blog/changelog/2026-11-18-customize-github-copilot-for-your-team/" target="_blank" rel="noreferrer">OFFICIAL_ANNOUNCEMENT · 2026-11-18</a></p><p>研究追溯：<a href="#a7">A7</a></p><p><span id="o10"></span></p><h3 id="o10-copilot-新增连接器强调管理员与服务方双边准入" tabindex="-1">O10 Copilot：新增连接器强调管理员与服务方双边准入 <a class="header-anchor" href="#o10-copilot-新增连接器强调管理员与服务方双边准入" aria-label="Permalink to &quot;O10 Copilot：新增连接器强调管理员与服务方双边准入&quot;">​</a></h3><p>11月18日新增八个公开预览连接器，包括 Supabase、Box、Calendly、Buildkite。可跨 App/CLI/VS Code 使用；Business/Enterprise 需启用预览策略，逐项 MCP allowlist 要加入新连接器，部分服务还需对方管理员开放。研究价值在准入与复用，不能从目录存在推导组织已有权限。</p><p>原始证据与状态：<a href="https://github.blog/changelog/2026-11-18-connect-supabase-box-calendly-and-more-to-copilot/" target="_blank" rel="noreferrer">OFFICIAL_ANNOUNCEMENT · 2026-11-18</a></p><p>研究追溯：<a href="#a7">A7</a></p><p><span id="o11"></span></p><h3 id="o11-codex-祖先上下文与子-agent-的授权证据分开" tabindex="-1">O11 Codex：祖先上下文与子 Agent 的授权证据分开 <a class="header-anchor" href="#o11-codex-祖先上下文与子-agent-的授权证据分开" aria-label="Permalink to &quot;O11 Codex：祖先上下文与子 Agent 的授权证据分开&quot;">​</a></h3><p>11月18日 #62314 已合入。prepared fork 可继承根 session ID 和祖先对话上下文，但启动、恢复及从存储重建 sender evidence 时排除祖先授权证据，仅保留子会话自身消息和授权；禁用插件设置继续继承。它直接约束委派时的证据归属。</p><p>原始证据与状态：<a href="https://github.com/openai/codex/pull/62314" target="_blank" rel="noreferrer">MERGED · 2026-11-18T16:37:38Z</a></p><p>研究追溯：<a href="#a2">A2</a></p><p><span id="o12"></span></p><h3 id="o12-codex-工具粒度选择审批人-受托管要求约束" tabindex="-1">O12 Codex：工具粒度选择审批人，受托管要求约束 <a class="header-anchor" href="#o12-codex-工具粒度选择审批人-受托管要求约束" aria-label="Permalink to &quot;O12 Codex：工具粒度选择审批人，受托管要求约束&quot;">​</a></h3><p>11月18日 #62360 已合入。单个 app tool 的 approvals_reviewer 可覆盖账号、app 和 session 默认配置，匹配原始工具名后再回退标题，并受 managed requirements 约束。作用于工具批准及匹配已验证 app 调用的 MCP 请求；不能据此将任意同名工具视为可信应用。</p><p>原始证据与状态：<a href="https://github.com/openai/codex/pull/62360" target="_blank" rel="noreferrer">MERGED · 2026-11-18T20:42:50Z</a></p><p>研究追溯：<a href="#a2">A2</a></p><p><span id="o13"></span></p><h3 id="o13-codex-guardian-审批前追齐证据-内存模式恢复有缺口" tabindex="-1">O13 Codex Guardian：审批前追齐证据，内存模式恢复有缺口 <a class="header-anchor" href="#o13-codex-guardian-审批前追齐证据-内存模式恢复有缺口" aria-label="Permalink to &quot;O13 Codex Guardian：审批前追齐证据，内存模式恢复有缺口&quot;">​</a></h3><p>11月18日 #62309/#62310 已合入：动作审批前追齐订阅证据，裁决前后核对原授权，准备失败阻断；共享截止时间。#62373 的可选内存 SQLite board 在冷恢复根会话时无法提供历史证据，附着 reviewer 因而不可用，磁盘仍默认。#62374 允许启用重考虑时对拒绝再采样一次，超时保留首次拒绝及理由。</p><p>原始证据与状态：<a href="https://github.com/openai/codex/pull/62309" target="_blank" rel="noreferrer">MERGED · 2026-11-18T16:18:30Z</a> · <a href="https://github.com/openai/codex/pull/62310" target="_blank" rel="noreferrer">MERGED · 2026-11-18T16:19:06Z</a> · <a href="https://github.com/openai/codex/pull/62373" target="_blank" rel="noreferrer">MERGED · 2026-11-18T21:58:08Z</a> · <a href="https://github.com/openai/codex/pull/62374" target="_blank" rel="noreferrer">MERGED · 2026-11-18T21:58:46Z</a></p><p>研究追溯：<a href="#a2">A2</a></p><p><span id="o14"></span></p><h3 id="o14-codex-暂停的是遥测完整性检查-沙箱执行约束仍在" tabindex="-1">O14 Codex：暂停的是遥测完整性检查，沙箱执行约束仍在 <a class="header-anchor" href="#o14-codex-暂停的是遥测完整性检查-沙箱执行约束仍在" aria-label="Permalink to &quot;O14 Codex：暂停的是遥测完整性检查，沙箱执行约束仍在&quot;">​</a></h3><p>11月19日 #62389 已合入。在 exec-server 和旧本地执行共享入口暂停重复的完整性依赖发现、策略准备与遥测，原因是与执行约束中的准备重复；checker 超时/错误的启动集成用例暂忽略，独立 checker 测试保留。不能把这一提交解释成关闭沙箱强制执行。</p><p>原始证据与状态：<a href="https://github.com/openai/codex/pull/62389" target="_blank" rel="noreferrer">MERGED · 2026-11-19T01:16:40Z</a></p><p>研究追溯：<a href="#a2">A2</a></p><p><span id="o15"></span></p><h3 id="o15-codex-父任务中断前先持久化已排队的子结果" tabindex="-1">O15 Codex：父任务中断前先持久化已排队的子结果 <a class="header-anchor" href="#o15-codex-父任务中断前先持久化已排队的子结果" aria-label="Permalink to &quot;O15 Codex：父任务中断前先持久化已排队的子结果&quot;">​</a></h3><p>11月18日 #62348 已合入。父 Agent 已确认子最终回复、尚未送入下次模型请求时，中断清理可能丢失消息；现在先写入历史并 flush，再发 TurnAborted，即使未写中断标记也一样。上游回归要求下次模型请求只出现一次。未在 CodeFlowMu 本地验证。</p><p>原始证据与状态：<a href="https://github.com/openai/codex/pull/62348" target="_blank" rel="noreferrer">MERGED · 2026-11-18T19:40:16Z</a></p><p>研究追溯：<a href="#a3">A3</a></p><p><span id="o16"></span></p><h3 id="o16-codex-轨迹缩减保留来源-同时说明关键路径缺失原因" tabindex="-1">O16 Codex：轨迹缩减保留来源，同时说明关键路径缺失原因 <a class="header-anchor" href="#o16-codex-轨迹缩减保留来源-同时说明关键路径缺失原因" aria-label="Permalink to &quot;O16 Codex：轨迹缩减保留来源，同时说明关键路径缺失原因&quot;">​</a></h3><p>11月18–19日 #62357/#62407 已合入。关键路径 incomplete 细分缺起点、未归属等待、强制结束等原因；轨迹大字符串按编码后64KiB阈值去重，完整捕获可逐字节重建，预算不足仍可能省略输出，但区分缺值与 null，并保留存活的终态元数据和工具结果 ID。不能将缩减轨迹当完整证据。</p><p>原始证据与状态：<a href="https://github.com/openai/codex/pull/62357" target="_blank" rel="noreferrer">MERGED · 2026-11-18T20:30:31Z</a> · <a href="https://github.com/openai/codex/pull/62407" target="_blank" rel="noreferrer">MERGED · 2026-11-19T02:41:31Z</a></p><p>研究追溯：<a href="#a3">A3</a></p><p><span id="o17"></span></p><h3 id="o17-codex-续跑保留原沙箱权限-跨平台路径保留原语义" tabindex="-1">O17 Codex：续跑保留原沙箱权限，跨平台路径保留原语义 <a class="header-anchor" href="#o17-codex-续跑保留原沙箱权限-跨平台路径保留原语义" aria-label="Permalink to &quot;O17 Codex：续跑保留原沙箱权限，跨平台路径保留原语义&quot;">​</a></h3><p>11月18日 #62194、#62376、#62377 已合入。续跑 codex exec 保留已存沙箱限制；跨操作系统客户端/服务器传递可写根和工作区根时保留源平台路径语义。它们是恢复与适配层变更，不证明任意平台组合都已本地验收。</p><p>原始证据与状态：<a href="https://github.com/openai/codex/pull/62194" target="_blank" rel="noreferrer">MERGED · 2026-11-18T05:14:25Z</a> · <a href="https://github.com/openai/codex/pull/62376" target="_blank" rel="noreferrer">MERGED · 2026-11-18T22:40:00Z</a> · <a href="https://github.com/openai/codex/pull/62377" target="_blank" rel="noreferrer">MERGED · 2026-11-18T22:40:38Z</a></p><p>研究追溯：<a href="#a4">A4</a></p><p><span id="o18"></span></p><h3 id="o18-codex-0-170-此前修复进入正式发行" tabindex="-1">O18 Codex 0.170：此前修复进入正式发行 <a class="header-anchor" href="#o18-codex-0-170-此前修复进入正式发行" aria-label="Permalink to &quot;O18 Codex 0.170：此前修复进入正式发行&quot;">​</a></h3><p>11月18日03:40 UTC 正式发行 rust-v0.170.0，晚于昨日检查起点。发行包含 MCP OAuth 取消/登录/登出竞争、Cloud 重连、子线程权限保留、Windows 权限与恢复等修复。本项新增是发行状态；历史合入不重复算新修复，今天新合入的 Guardian 等能力也不能自动归入此安装包。</p><p>原始证据与状态：<a href="https://github.com/openai/codex/releases/tag/rust-v0.170.0" target="_blank" rel="noreferrer">RELEASED · 2026-11-18T03:40:48Z</a></p><p>研究追溯：<a href="#a4">A4</a> · <a href="#a7">A7</a></p><p><span id="o19"></span></p><h3 id="o19-claude-code-2-1-328-hook-失败阻断与审计阶段发生变化" tabindex="-1">O19 Claude Code 2.1.328：hook 失败阻断与审计阶段发生变化 <a class="header-anchor" href="#o19-claude-code-2-1-328-hook-失败阻断与审计阶段发生变化" aria-label="Permalink to &quot;O19 Claude Code 2.1.328：hook 失败阻断与审计阶段发生变化&quot;">​</a></h3><p>11月19日正式发行。mcp_tool hook 新增 onFailure:block；宿主可禁止恢复 hook 延迟的工具调用。Code Mode 脚本输出不再触发 UserPromptSubmit，脱敏改走 PostToolUse updatedToolOutput；执行前已拒绝的调用不再触发 managed PostToolUse。升级后要核对原审计/脱敏挂接点，不能把缺日志解释成未尝试动作。</p><p>原始证据与状态：<a href="https://github.com/anthropics/claude-code/releases/tag/v2.1.328" target="_blank" rel="noreferrer">RELEASED · 2026-11-19T01:14:04Z</a></p><p>研究追溯：<a href="#a2">A2</a></p><p><span id="o20"></span></p><h3 id="o20-claude-code-自托管恢复避免把异常响应当成停工指令" tabindex="-1">O20 Claude Code：自托管恢复避免把异常响应当成停工指令 <a class="header-anchor" href="#o20-claude-code-自托管恢复避免把异常响应当成停工指令" aria-label="Permalink to &quot;O20 Claude Code：自托管恢复避免把异常响应当成停工指令&quot;">​</a></h3><p>同一 v2.1.328 发行修复代理返回 HTTP200 加空对象导致全部会话停止、临时磁盘错误导致保留克隆数据误删，并为已注册后启动失败补注销原因。特定非 fork 子 Agent 模式默认等待自己的子 Agent；恢复后检查先前工作是否仍存在。均为上游发行说明，本机未复现。</p><p>原始证据与状态：<a href="https://github.com/anthropics/claude-code/releases/tag/v2.1.328" target="_blank" rel="noreferrer">RELEASED · 2026-11-19T01:14:04Z</a></p><p>研究追溯：<a href="#a4">A4</a></p><p><span id="o21"></span></p><h3 id="o21-gemini-cli-确认依据要对应真正执行的-shell-参数" tabindex="-1">O21 Gemini CLI：确认依据要对应真正执行的 shell 参数 <a class="header-anchor" href="#o21-gemini-cli-确认依据要对应真正执行的-shell-参数" aria-label="Permalink to &quot;O21 Gemini CLI：确认依据要对应真正执行的 shell 参数&quot;">​</a></h3><p>11月18日 #30338/#30355 已合入。含未解析 Bash 展开时保留 ASK_USER，解析失败也保守处理；显式允许规则不因此撤销，PowerShell 不在前一修复范围。commandPrefix/commandRegex 只匹配顶层 command，正则分支保持在字段内。不能用嵌套字段或展开前的文本冒充已核验命令。</p><p>原始证据与状态：<a href="https://github.com/google-gemini/gemini-cli/pull/30338" target="_blank" rel="noreferrer">MERGED · 2026-11-18T19:39:26Z</a> · <a href="https://github.com/google-gemini/gemini-cli/pull/30355" target="_blank" rel="noreferrer">MERGED · 2026-11-18T21:21:44Z</a></p><p>研究追溯：<a href="#a1">A1</a></p><p><span id="o22"></span></p><h3 id="o22-langgraph-工具调用状态覆盖终于进入实际工具-runtime" tabindex="-1">O22 LangGraph：工具调用状态覆盖终于进入实际工具 runtime <a class="header-anchor" href="#o22-langgraph-工具调用状态覆盖终于进入实际工具-runtime" aria-label="Permalink to &quot;O22 LangGraph：工具调用状态覆盖终于进入实际工具 runtime&quot;">​</a></h3><p>11月18日 #9730 已合入。override(state=...) 原先只改 request，InjectedState 和 ToolRuntime 仍见旧状态；现在同步替换 runtime.state，嵌套 wrapper 也看到同一状态，同时给 state 与旧 runtime 时 state 优先。对动作前策略，需要核查实际工具读到的状态，而非只检查外层请求。</p><p>原始证据与状态：<a href="https://github.com/langchain-ai/langgraph/pull/9730" target="_blank" rel="noreferrer">MERGED · 2026-11-18T21:33:00Z</a></p><p>研究追溯：<a href="#a1">A1</a> · <a href="#a6">A6</a></p><p><span id="o23"></span></p><h3 id="o23-langchain-人工拒绝-回答形成的工具消息显式标来源" tabindex="-1">O23 LangChain：人工拒绝/回答形成的工具消息显式标来源 <a class="header-anchor" href="#o23-langchain-人工拒绝-回答形成的工具消息显式标来源" aria-label="Permalink to &quot;O23 LangChain：人工拒绝/回答形成的工具消息显式标来源&quot;">​</a></h3><p>11月18日 #41928 已合入并进入 langchain 1.5.2。人工拒绝和人工代答生成的 ToolMessage 带 lc_source 和 decision，真实工具在批准/编辑后运行的结果不贴该标签。元数据用于辨认来源，不是可信度或授权证明。</p><p>原始证据与状态：<a href="https://github.com/langchain-ai/langchain/pull/41928" target="_blank" rel="noreferrer">MERGED · 2026-11-18T21:41:09Z</a> · <a href="https://github.com/langchain-ai/langchain/releases/tag/langchain%3D%3D1.5.2" target="_blank" rel="noreferrer">RELEASED · 2026-11-18T22:30:43Z</a></p><p>研究追溯：<a href="#a3">A3</a></p><p><span id="o24"></span></p><h3 id="o24-langchain-分开异步连接-避免不同模型实例共享已关闭事件循环" tabindex="-1">O24 LangChain：分开异步连接，避免不同模型实例共享已关闭事件循环 <a class="header-anchor" href="#o24-langchain-分开异步连接-避免不同模型实例共享已关闭事件循环" aria-label="Permalink to &quot;O24 LangChain：分开异步连接，避免不同模型实例共享已关闭事件循环&quot;">​</a></h3><p>11月18日 #41944 已合入，langchain-openai 1.8.2 已发行。每个模型实例独有异步 HTTP client，仅复用 SSL 配置，避免新实例继承已关闭事件循环的连接。同一模型实例跨事件循环仍不支持；频繁创建模型可能增加连接数。</p><p>原始证据与状态：<a href="https://github.com/langchain-ai/langchain/pull/41944" target="_blank" rel="noreferrer">MERGED · 2026-11-18T16:41:45Z</a> · <a href="https://github.com/langchain-ai/langchain/releases/tag/langchain-openai%3D%3D1.8.2" target="_blank" rel="noreferrer">RELEASED · 2026-11-18T16:53:05Z</a></p><p>研究追溯：<a href="#a5">A5</a></p><p><span id="o25"></span></p><h3 id="o25-crewai-1-15-42-默认知识库改变-持久化需要显式配置" tabindex="-1">O25 CrewAI 1.15.42：默认知识库改变，持久化需要显式配置 <a class="header-anchor" href="#o25-crewai-1-15-42-默认知识库改变-持久化需要显式配置" aria-label="Permalink to &quot;O25 CrewAI 1.15.42：默认知识库改变，持久化需要显式配置&quot;">​</a></h3><p>11月18日 #8941 已合入且1.15.42发行。ChromaDB 变为额外依赖，默认知识库/搜索转向本地 Qdrant；旧 Chroma 数据不自动读取或迁移。默认路径按进程隔离并在退出时删除，重启会重建嵌入；固定本地目录只能单进程使用，多进程需服务端或保留 Chroma。默认嵌入仍用 OpenAI，不能把本地向量库当离线运行。</p><p>原始证据与状态：<a href="https://github.com/crewAIInc/crewAI/pull/8941" target="_blank" rel="noreferrer">MERGED · 2026-11-18T14:56:52Z</a> · <a href="https://github.com/crewAIInc/crewAI/releases/tag/1.15.42" target="_blank" rel="noreferrer">RELEASED · 2026-11-18T16:38:31Z</a></p><p>研究追溯：<a href="#a5">A5</a> · <a href="#a7">A7</a></p><p><span id="o26"></span></p><h3 id="o26-crewai-flow-默认状态实例不再让不同运行共用-id" tabindex="-1">O26 CrewAI：Flow 默认状态实例不再让不同运行共用 ID <a class="header-anchor" href="#o26-crewai-flow-默认状态实例不再让不同运行共用-id" aria-label="Permalink to &quot;O26 CrewAI：Flow 默认状态实例不再让不同运行共用 ID&quot;">​</a></h3><p>11月18日 #9499 已合入并进入1.15.42。类级 initial_state=S() 原来复用默认生成 ID，持久化时可能写入同一个 flow_uuid；现在对该类默认生成新 ID，显式固定 ID 和传入旧状态续跑仍保留。不能把有意续跑与意外跨运行合并混为一谈。</p><p>原始证据与状态：<a href="https://github.com/crewAIInc/crewAI/pull/9499" target="_blank" rel="noreferrer">MERGED · 2026-11-18T05:23:53Z</a> · <a href="https://github.com/crewAIInc/crewAI/releases/tag/1.15.42" target="_blank" rel="noreferrer">RELEASED · 2026-11-18T16:38:31Z</a></p><p>研究追溯：<a href="#a3">A3</a> · <a href="#a5">A5</a></p><p><span id="o27"></span></p><h3 id="o27-crewai-独立-kickoff-的执行时限修复仍开放" tabindex="-1">O27 CrewAI：独立 kickoff 的执行时限修复仍开放 <a class="header-anchor" href="#o27-crewai-独立-kickoff-的执行时限修复仍开放" aria-label="Permalink to &quot;O27 CrewAI：独立 kickoff 的执行时限修复仍开放&quot;">​</a></h3><p>11月18日新建 #9539，当前 OPEN、非 draft、未合入。提案补独立 kickoff/kickoff_async 未读取 max_execution_time 的路径；作者明确新测试因环境依赖未运行。1.15.42 已发行的既有 execute_task 超时修复仅让调用方及时返回，不能杀死已运行 Python 线程；这两条路径和停止副作用不能混称已解决。旧 #9324 不重复计新合入。</p><p>原始证据与状态：<a href="https://github.com/crewAIInc/crewAI/pull/9539" target="_blank" rel="noreferrer">OPEN · 2026-11-18T09:42:45Z</a> · <a href="https://github.com/crewAIInc/crewAI/pull/9324" target="_blank" rel="noreferrer">MERGED · 2026-11-16T16:53:26Z</a> · <a href="https://github.com/crewAIInc/crewAI/releases/tag/1.15.42" target="_blank" rel="noreferrer">RELEASED · 2026-11-18T16:38:31Z</a></p><p>研究追溯：<a href="#a4">A4</a></p><p><span id="o28"></span></p><h3 id="o28-paperclip-pr-交付物真正合入后才允许任务完成" tabindex="-1">O28 Paperclip：PR 交付物真正合入后才允许任务完成 <a class="header-anchor" href="#o28-paperclip-pr-交付物真正合入后才允许任务完成" aria-label="Permalink to &quot;O28 Paperclip：PR 交付物真正合入后才允许任务完成&quot;">​</a></h3><p>11月19日 #22244 已合入。声明为交付物的 PR 必须经 GitHub 核实合入；OPEN、DRAFT、关闭未合入、无法读取或畸形链接都拒绝完成，不接受 Agent 自写 merged 状态。状态锁内重查当前交付物，远端读取放在事务外，既有评审仍可先开展。学习价值和交付治理竞争关注均高，主雷达不变；该合入晚于本轮稳定版发布。</p><p>原始证据与状态：<a href="https://github.com/paperclipai/paperclip/pull/22244" target="_blank" rel="noreferrer">MERGED · 2026-11-19T00:20:18Z</a></p><p>研究追溯：<a href="#a3">A3</a> · <a href="#a7">A7</a></p><p><span id="o29"></span></p><h3 id="o29-paperclip-恢复区分进程重启、任务锁与不可成功的重试" tabindex="-1">O29 Paperclip：恢复区分进程重启、任务锁与不可成功的重试 <a class="header-anchor" href="#o29-paperclip-恢复区分进程重启、任务锁与不可成功的重试" aria-label="Permalink to &quot;O29 Paperclip：恢复区分进程重启、任务锁与不可成功的重试&quot;">​</a></h3><p>11月18日三项已合入：#22235 对同执行中恢复丢失的 turn 允许一次同会话续接；#22239 记录该运行诊断期的 sandbox_disk_full，禁止换同尺寸沙箱重复尝试；#22248 在执行器仍结算终态运行时保留任务锁，避免用量等待的取消/排重试竞争。昨天的磁盘预留只覆盖恢复入口，并不保证 turn 和任务都恢复。学习价值高，提高恢复机制关注。</p><p>原始证据与状态：<a href="https://github.com/paperclipai/paperclip/pull/22235" target="_blank" rel="noreferrer">MERGED · 2026-11-18T21:55:16Z</a> · <a href="https://github.com/paperclipai/paperclip/pull/22239" target="_blank" rel="noreferrer">MERGED · 2026-11-18T23:19:13Z</a> · <a href="https://github.com/paperclipai/paperclip/pull/22248" target="_blank" rel="noreferrer">MERGED · 2026-11-18T23:39:15Z</a></p><p>研究追溯：<a href="#a4">A4</a> · <a href="#a5">A5</a> · <a href="#a7">A7</a></p><p><span id="o30"></span></p><h3 id="o30-paperclip-公司工作负载身份连接到按连接铸发的-aws-凭证" tabindex="-1">O30 Paperclip：公司工作负载身份连接到按连接铸发的 AWS 凭证 <a class="header-anchor" href="#o30-paperclip-公司工作负载身份连接到按连接铸发的-aws-凭证" aria-label="Permalink to &quot;O30 Paperclip：公司工作负载身份连接到按连接铸发的 AWS 凭证&quot;">​</a></h3><p>11月18日 #22083/#22195 已合入。每公司签名密钥、issuer/JWKS 与轮换审计为按连接发 token 提供基础；AWS 连接器实验开关下可按角色或密钥建立会话，限制只读会话策略、缓存及去重。401 后清 token 并重铸，但要求显式重试，不自动重放原动作。身份基础合入时原本尚无使用者，后续 AWS PR 才接入。学习/企业身份竞争关注高。</p><p>原始证据与状态：<a href="https://github.com/paperclipai/paperclip/pull/22083" target="_blank" rel="noreferrer">MERGED · 2026-11-18T05:33:48Z</a> · <a href="https://github.com/paperclipai/paperclip/pull/22195" target="_blank" rel="noreferrer">MERGED · 2026-11-18T18:48:50Z</a></p><p>研究追溯：<a href="#a2">A2</a> · <a href="#a7">A7</a></p><p><span id="o31"></span></p><h3 id="o31-paperclip-人工启动例程应使用调用者身份" tabindex="-1">O31 Paperclip：人工启动例程应使用调用者身份 <a class="header-anchor" href="#o31-paperclip-人工启动例程应使用调用者身份" aria-label="Permalink to &quot;O31 Paperclip：人工启动例程应使用调用者身份&quot;">​</a></h3><p>11月18日 #22177 已合入。另一人 Run now 时，队列原先可能在例程事务提交前读不到新记录，错误使用保存者账号；现在把已选负责用户带入唤醒上下文，保存的例程所有者不变。上游有 PostgreSQL/heartbeat 前后对照，本轮未本地复现。学习价值高，关注跨用户执行身份。</p><p>原始证据与状态：<a href="https://github.com/paperclipai/paperclip/pull/22177" target="_blank" rel="noreferrer">MERGED · 2026-11-18T15:03:59Z</a></p><p>研究追溯：<a href="#a2">A2</a></p><p><span id="o32"></span></p><h3 id="o32-paperclip-工具授权先过安装门槛-再解析会话内别名" tabindex="-1">O32 Paperclip：工具授权先过安装门槛，再解析会话内别名 <a class="header-anchor" href="#o32-paperclip-工具授权先过安装门槛-再解析会话内别名" aria-label="Permalink to &quot;O32 Paperclip：工具授权先过安装门槛，再解析会话内别名&quot;">​</a></h3><p>11月18日 #22237/#22213 已合入。plugin 连接必须安装给 Agent 或公司，检查先于 grants、trust 和 allow；直接按名字调用也不能绕过。赋权工具别名可接受唯一匹配的显示名/网关名，仍在 session 固定目录及新鲜授权过滤内，歧义时报错。学习价值高，授权覆盖面竞争关注提高，主雷达不变。</p><p>原始证据与状态：<a href="https://github.com/paperclipai/paperclip/pull/22237" target="_blank" rel="noreferrer">MERGED · 2026-11-18T23:34:10Z</a> · <a href="https://github.com/paperclipai/paperclip/pull/22213" target="_blank" rel="noreferrer">MERGED · 2026-11-18T21:24:46Z</a></p><p>研究追溯：<a href="#a2">A2</a> · <a href="#a7">A7</a></p><p><span id="o33"></span></p><h3 id="o33-paperclip-claude-mcp-bearer-token-移出命令行" tabindex="-1">O33 Paperclip：Claude MCP bearer token 移出命令行 <a class="header-anchor" href="#o33-paperclip-claude-mcp-bearer-token-移出命令行" aria-label="Permalink to &quot;O33 Paperclip：Claude MCP bearer token 移出命令行&quot;">​</a></h3><p>11月18日 #22206 已合入。上游发现 ps 输出会把内联 --mcp-config token 留进工具日志；Claude ACPX 路径改为环境变量引用，由 Claude 展开。其他 ACPX agent 因无已知展开支持仍用原头部；环境变量也不等于凭证对同权限代码不可读。学习价值高，凭证隔离继续专项观察。</p><p>原始证据与状态：<a href="https://github.com/paperclipai/paperclip/pull/22206" target="_blank" rel="noreferrer">MERGED · 2026-11-18T21:58:47Z</a></p><p>研究追溯：<a href="#a2">A2</a></p><p><span id="o34"></span></p><h3 id="o34-paperclip-在线迁移持久数据采用有预算、可延后的一轮处理" tabindex="-1">O34 Paperclip：在线迁移持久数据采用有预算、可延后的一轮处理 <a class="header-anchor" href="#o34-paperclip-在线迁移持久数据采用有预算、可延后的一轮处理" aria-label="Permalink to &quot;O34 Paperclip：在线迁移持久数据采用有预算、可延后的一轮处理&quot;">​</a></h3><p>11月18日 #22240 已合入。S3 与持久 Agent 文件配置满足后，在线按60秒预算迁移文件、技能和运行备份等，忙项延后、返回进度及明确配置阻碍，既有 CAS/认领处理并发写。目标是无维护窗口转无卷服务器，上游目标不等于所有部署已完成零停机迁移。学习价值高，交付成熟度待体验。</p><p>原始证据与状态：<a href="https://github.com/paperclipai/paperclip/pull/22240" target="_blank" rel="noreferrer">MERGED · 2026-11-18T23:36:31Z</a></p><p>研究追溯：<a href="#a4">A4</a> · <a href="#a7">A7</a></p><p><span id="o35"></span></p><h3 id="o35-paperclip-稳定版发行-新交付状态与破坏性连接器设置" tabindex="-1">O35 Paperclip 稳定版发行：新交付状态与破坏性连接器设置 <a class="header-anchor" href="#o35-paperclip-稳定版发行-新交付状态与破坏性连接器设置" aria-label="Permalink to &quot;O35 Paperclip 稳定版发行：新交付状态与破坏性连接器设置&quot;">​</a></h3><p>v2026.1117.0 于11月18日22:20 UTC 正式发布，说明中的 Released:11月17日与实际发布事件需分开。默认 Coordinator/Agent Chat 和恢复等既有成果进入本发行；内置 Google Workspace 因验证未完成默认关闭，包括旧连接执行，需显式实验设置启用。1586个历史提交不算1586项当天新增；发行后的任务完成校验等不能据此认定已打包。学习价值高，主雷达交付关注提高；MIT 已核验。</p><p>原始证据与状态：<a href="https://github.com/paperclipai/paperclip/releases/tag/v2026.1117.0" target="_blank" rel="noreferrer">RELEASED · 2026-11-18T22:20:29Z</a></p><p>研究追溯：<a href="#a2">A2</a> · <a href="#a7">A7</a></p><p><span id="o36"></span></p><h3 id="o36-orca-手机合并绑定用户看过的-pr-head" tabindex="-1">O36 Orca：手机合并绑定用户看过的 PR head <a class="header-anchor" href="#o36-orca-手机合并绑定用户看过的-pr-head" aria-label="Permalink to &quot;O36 Orca：手机合并绑定用户看过的 PR head&quot;">​</a></h3><p>11月19日 #44354 已合入。手机提交 expectedHeadSha，主机读取最新 PR 后比较，并在合并命令继续要求同一 head；有人在页面加载后推送新提交会拒绝并要求刷新。学习价值高，移动审批竞争关注提高，第二圈不变；本轮未做手机实机体验。</p><p>原始证据与状态：<a href="https://github.com/stablyai/orca/pull/44354" target="_blank" rel="noreferrer">MERGED · 2026-11-19T00:22:34Z</a></p><p>研究追溯：<a href="#a2">A2</a> · <a href="#a7">A7</a></p><p><span id="o37"></span></p><h3 id="o37-orca-浏览器工作区与远端宿主权限不再静默回退" tabindex="-1">O37 Orca：浏览器工作区与远端宿主权限不再静默回退 <a class="header-anchor" href="#o37-orca-浏览器工作区与远端宿主权限不再静默回退" aria-label="Permalink to &quot;O37 Orca：浏览器工作区与远端宿主权限不再静默回退&quot;">​</a></h3><p>11月18–19日 #44237/#43958 已合入。聊天 Agent 在工作区外未指定 page 的浏览器操作直接拒绝，避免接管用户全局活动页；terminal/computer 相同回退暴露不在此前修复范围。配对主机启动若会误用桌面 full-access 配置则拒绝，不把本机跳过权限设置带过去。学习/跨宿主治理关注高，圈层不变。</p><p>原始证据与状态：<a href="https://github.com/stablyai/orca/pull/44237" target="_blank" rel="noreferrer">MERGED · 2026-11-19T02:28:59Z</a> · <a href="https://github.com/stablyai/orca/pull/43958" target="_blank" rel="noreferrer">MERGED · 2026-11-18T07:16:43Z</a></p><p>研究追溯：<a href="#a2">A2</a> · <a href="#a7">A7</a></p><p><span id="o38"></span></p><h3 id="o38-orca-停止要有退出证明-空闲期死亡也要通知协调者" tabindex="-1">O38 Orca：停止要有退出证明，空闲期死亡也要通知协调者 <a class="header-anchor" href="#o38-orca-停止要有退出证明-空闲期死亡也要通知协调者" aria-label="Permalink to &quot;O38 Orca：停止要有退出证明，空闲期死亡也要通知协调者&quot;">​</a></h3><p>11月18–19日 #43953/#43955 已合入。停止证实并保存输出引用后，在同事务释放 worker 终端；历史卡住资源仅对已证明 exited 的进程回收，离线/不确定的不释放。无活跃 turn 时 provider 意外退出也为开放 Dispatch 发送带 generation fence 的退出报告，避免协调者永久等待。学习/生命周期竞争关注高。</p><p>原始证据与状态：<a href="https://github.com/stablyai/orca/pull/43953" target="_blank" rel="noreferrer">MERGED · 2026-11-19T02:03:56Z</a> · <a href="https://github.com/stablyai/orca/pull/43955" target="_blank" rel="noreferrer">MERGED · 2026-11-18T20:18:19Z</a></p><p>研究追溯：<a href="#a3">A3</a> · <a href="#a4">A4</a> · <a href="#a7">A7</a></p><p><span id="o39"></span></p><h3 id="o39-orca-子-agent-审批、批准理由与完成投影补齐" tabindex="-1">O39 Orca：子 Agent 审批、批准理由与完成投影补齐 <a class="header-anchor" href="#o39-orca-子-agent-审批、批准理由与完成投影补齐" aria-label="Permalink to &quot;O39 Orca：子 Agent 审批、批准理由与完成投影补齐&quot;">​</a></h3><p>11月18–19日 #44302/#43858/#44375 已合入。子 Agent 许可问题上报前短暂等待真实对话框出现；协调者批准理由送达 worker 并有回执；配对桌面/手机在 Pi 根回复结束、后台子任务仍运行时继续显示工作中。学习价值高，避免把证据尚未出现或根回复结束当作流程完成。</p><p>原始证据与状态：<a href="https://github.com/stablyai/orca/pull/44302" target="_blank" rel="noreferrer">MERGED · 2026-11-18T23:04:10Z</a> · <a href="https://github.com/stablyai/orca/pull/43858" target="_blank" rel="noreferrer">MERGED · 2026-11-18T03:04:13Z</a> · <a href="https://github.com/stablyai/orca/pull/44375" target="_blank" rel="noreferrer">MERGED · 2026-11-19T01:02:11Z</a></p><p>研究追溯：<a href="#a3">A3</a> · <a href="#a7">A7</a></p><p><span id="o40"></span></p><h3 id="o40-orca-跨主机邮件有能力协商-改变任务的消息留在主控侧" tabindex="-1">O40 Orca：跨主机邮件有能力协商，改变任务的消息留在主控侧 <a class="header-anchor" href="#o40-orca-跨主机邮件有能力协商-改变任务的消息留在主控侧" aria-label="Permalink to &quot;O40 Orca：跨主机邮件有能力协商，改变任务的消息留在主控侧&quot;">​</a></h3><p>11月18日 #44034 已合入。配对服务器可传 status/handoff/question/dispatch/merge_ready；新类型发送前检查 peer-mail-types.v1，旧服务器不支持时明确未发送。会改变 Dispatch 的 escalation/decision_gate/worker_done/heartbeat 仍由 Run 主机执行及核权。学习价值高，是消息互操作与状态权威分层的直接材料。</p><p>原始证据与状态：<a href="https://github.com/stablyai/orca/pull/44034" target="_blank" rel="noreferrer">MERGED · 2026-11-18T23:23:29Z</a></p><p>研究追溯：<a href="#a6">A6</a> · <a href="#a7">A7</a></p><p><span id="o41"></span></p><h3 id="o41-orca-手机命令和启动顺序显式区分支持范围" tabindex="-1">O41 Orca：手机命令和启动顺序显式区分支持范围 <a class="header-anchor" href="#o41-orca-手机命令和启动顺序显式区分支持范围" aria-label="Permalink to &quot;O41 Orca：手机命令和启动顺序显式区分支持范围&quot;">​</a></h3><p>11月18–19日 #44250/#43978 已合入。结构化手机聊天支持 /fork、/usage，/resume 与 /btw 显示仅桌面可用，避免作为普通指令发给 Agent；手机创建工作区可要求 setup 完成后才启动 Agent。仅覆盖对应结构化聊天和有 setup 的项目，PR 正文旧待审提示不等于当前未合入。学习价值中高，移动控制继续第二圈专项观察。</p><p>原始证据与状态：<a href="https://github.com/stablyai/orca/pull/44250" target="_blank" rel="noreferrer">MERGED · 2026-11-19T02:31:32Z</a> · <a href="https://github.com/stablyai/orca/pull/43978" target="_blank" rel="noreferrer">MERGED · 2026-11-18T22:43:14Z</a></p><p>研究追溯：<a href="#a7">A7</a></p><p><span id="o42"></span></p><h3 id="o42-orca-慢客户端与历史追赶不再无限积压快照" tabindex="-1">O42 Orca：慢客户端与历史追赶不再无限积压快照 <a class="header-anchor" href="#o42-orca-慢客户端与历史追赶不再无限积压快照" aria-label="Permalink to &quot;O42 Orca：慢客户端与历史追赶不再无限积压快照&quot;">​</a></h3><p>11月18日 #43456 已合入。每订阅者一次交付，等待中的流文本只保留最新快照，catch-up 合并但不越过有序操作；历史读取的并发和排队量一起限制。journal 写入、cursor 与 fence 保持原语义。学习价值高，长期运行内存治理值得体验，尚未本机压测。</p><p>原始证据与状态：<a href="https://github.com/stablyai/orca/pull/43456" target="_blank" rel="noreferrer">MERGED · 2026-11-18T23:34:21Z</a></p><p>研究追溯：<a href="#a4">A4</a> · <a href="#a5">A5</a> · <a href="#a7">A7</a></p><p><span id="o43"></span></p><h3 id="o43-orca-远端浏览器登录跨重启持久化-隔离范围需随之核对" tabindex="-1">O43 Orca：远端浏览器登录跨重启持久化，隔离范围需随之核对 <a class="header-anchor" href="#o43-orca-远端浏览器登录跨重启持久化-隔离范围需随之核对" aria-label="Permalink to &quot;O43 Orca：远端浏览器登录跨重启持久化，隔离范围需随之核对&quot;">​</a></h3><p>11月18日 #43956 已合入。SSH/This-device 路由分区保存各自密封 session-cookie 快照，首次页面载入前恢复，This-device 支持密码保存与填充。持续登录有产品价值，也扩大跨端凭证持久化研究范围；未验证本地跨用户/宿主隔离，竞争关注中高，圈层不变。</p><p>原始证据与状态：<a href="https://github.com/stablyai/orca/pull/43956" target="_blank" rel="noreferrer">MERGED · 2026-11-18T23:54:32Z</a></p><p>研究追溯：<a href="#a2">A2</a> · <a href="#a7">A7</a></p><p><span id="o44"></span></p><h3 id="o44-beads-认领要核对阻塞-审计要覆盖真实认领路径" tabindex="-1">O44 Beads：认领要核对阻塞，审计要覆盖真实认领路径 <a class="header-anchor" href="#o44-beads-认领要核对阻塞-审计要覆盖真实认领路径" aria-label="Permalink to &quot;O44 Beads：认领要核对阻塞，审计要覆盖真实认领路径&quot;">​</a></h3><p>11月18日 #8360/#8336/#8024 已合入。认领在事务内检查本地阻塞，显式 force 是独立覆盖；audit.enabled 时认领与 claim-next 的直接/代理路径都记入 sidecar。事件 old_value 改为被修改字段的前像，认领无前态的路径不虚构旧值。学习价值高，任务认领语义与事件证据继续主雷达研究。</p><p>原始证据与状态：<a href="https://github.com/gastownhall/beads/pull/8360" target="_blank" rel="noreferrer">MERGED · 2026-11-18T19:20:28Z</a> · <a href="https://github.com/gastownhall/beads/pull/8336" target="_blank" rel="noreferrer">MERGED · 2026-11-18T20:07:41Z</a> · <a href="https://github.com/gastownhall/beads/pull/8024" target="_blank" rel="noreferrer">MERGED · 2026-11-18T13:35:27Z</a></p><p>研究追溯：<a href="#a3">A3</a> · <a href="#a6">A6</a> · <a href="#a7">A7</a></p><p><span id="o45"></span></p><h3 id="o45-beads-导入远端项目历史要同意-跨项目数据库要核身份" tabindex="-1">O45 Beads：导入远端项目历史要同意，跨项目数据库要核身份 <a class="header-anchor" href="#o45-beads-导入远端项目历史要同意-跨项目数据库要核身份" aria-label="Permalink to &quot;O45 Beads：导入远端项目历史要同意，跨项目数据库要核身份&quot;">​</a></h3><p>11月18日 #8353/#8475 已合入。bd init 从 git origin 接纳 Dolt 历史改为默认拒绝的同意流程，非交互环境需显式选择；普通代理工作区显式切到其他数据库时先做只读项目身份检查，再允许 attach/migration。并非所有数据库打开都被严格新门禁覆盖。学习价值高，关注多项目污染及部署边界。</p><p>原始证据与状态：<a href="https://github.com/gastownhall/beads/pull/8353" target="_blank" rel="noreferrer">MERGED · 2026-11-18T19:37:52Z</a> · <a href="https://github.com/gastownhall/beads/pull/8475" target="_blank" rel="noreferrer">MERGED · 2026-11-18T15:42:06Z</a></p><p>研究追溯：<a href="#a2">A2</a> · <a href="#a7">A7</a></p><p><span id="o46"></span></p><h3 id="o46-beads-事务回滚不能留下看似已存在的工件-id" tabindex="-1">O46 Beads：事务回滚不能留下看似已存在的工件 ID <a class="header-anchor" href="#o46-beads-事务回滚不能留下看似已存在的工件-id" aria-label="Permalink to &quot;O46 Beads：事务回滚不能留下看似已存在的工件 ID&quot;">​</a></h3><p>11月18日 #8470/#8464 已合入。创建事务回滚后清空写到调用者结构体的自动 ID，代理导入重试重新为未设置 ID 的对象分配，避免把上次尝试的未提交标识当成功对象。学习价值高，值得对照文件/工件契约中的身份和提交回执，尚未做本地对照。</p><p>原始证据与状态：<a href="https://github.com/gastownhall/beads/pull/8470" target="_blank" rel="noreferrer">MERGED · 2026-11-18T20:10:43Z</a> · <a href="https://github.com/gastownhall/beads/pull/8464" target="_blank" rel="noreferrer">MERGED · 2026-11-18T15:55:58Z</a></p><p>研究追溯：<a href="#a3">A3</a> · <a href="#a6">A6</a> · <a href="#a7">A7</a></p><p><span id="o47"></span></p><h3 id="o47-beads-迁移中止要说明可能残留的部分写入" tabindex="-1">O47 Beads：迁移中止要说明可能残留的部分写入 <a class="header-anchor" href="#o47-beads-迁移中止要说明可能残留的部分写入" aria-label="Permalink to &quot;O47 Beads：迁移中止要说明可能残留的部分写入&quot;">​</a></h3><p>11月18日 #8361 已合入。特定 schema-encoding drift 返回带迁移号、游标及 runbook 的类型化错误，首错即停；不跳过、不自动重试或回滚，部分未提交修改可能留存，原始引擎 panic 也不由此拦截。学习价值高，延续昨日候选版迁移风险观察；MIT 已核验。</p><p>原始证据与状态：<a href="https://github.com/gastownhall/beads/pull/8361" target="_blank" rel="noreferrer">MERGED · 2026-11-18T18:11:03Z</a></p><p>研究追溯：<a href="#a4">A4</a> · <a href="#a7">A7</a></p><p><span id="o48"></span></p><h3 id="o48-openhands-agent-发来的消息保留会话发送者-不能冒充用户" tabindex="-1">O48 OpenHands：Agent 发来的消息保留会话发送者，不能冒充用户 <a class="header-anchor" href="#o48-openhands-agent-发来的消息保留会话发送者-不能冒充用户" aria-label="Permalink to &quot;O48 OpenHands：Agent 发来的消息保留会话发送者，不能冒充用户&quot;">​</a></h3><p>11月18日 #6960/#6975 已合入。REST 发送/初始消息可带 sender_conversation_id，子任务初始消息记录父会话来源；外来会话消息附说明，不代表用户批准。sender 可用于 hooks 和可视化，主 App 前端尚未读取；非用户 sender 的运行确认门禁是独立后续，不能称完整授权闭环已完成。</p><p>原始证据与状态：<a href="https://github.com/OpenHands/software-agent-sdk/pull/6960" target="_blank" rel="noreferrer">MERGED · 2026-11-18T19:21:06Z</a> · <a href="https://github.com/OpenHands/software-agent-sdk/pull/6975" target="_blank" rel="noreferrer">MERGED · 2026-11-18T23:26:51Z</a></p><p>研究追溯：<a href="#a2">A2</a> · <a href="#a3">A3</a></p><p><span id="o49"></span></p><h3 id="o49-openhands-健康检查仍绿-也可能因线程池锁等待死锁" tabindex="-1">O49 OpenHands：健康检查仍绿，也可能因线程池锁等待死锁 <a class="header-anchor" href="#o49-openhands-健康检查仍绿-也可能因线程池锁等待死锁" aria-label="Permalink to &quot;O49 OpenHands：健康检查仍绿，也可能因线程池锁等待死锁&quot;">​</a></h3><p>11月18日 #6554 已合入。持状态锁的工具执行和等待同一锁的请求共用默认线程池，客户端风暴可耗尽线程、全服务僵住而 /alive 仍绿。改为顺序工具专用池、每会话状态操作池，并把长历史重放移出事件循环。上游故障机制与修复已核查，未本地压测。</p><p>原始证据与状态：<a href="https://github.com/OpenHands/software-agent-sdk/pull/6554" target="_blank" rel="noreferrer">MERGED · 2026-11-18T17:43:32Z</a></p><p>研究追溯：<a href="#a4">A4</a></p><p><span id="o50"></span></p><h3 id="o50-openhands-模型路由拥有切换状态-运行时可追加路线" tabindex="-1">O50 OpenHands：模型路由拥有切换状态，运行时可追加路线 <a class="header-anchor" href="#o50-openhands-模型路由拥有切换状态-运行时可追加路线" aria-label="Permalink to &quot;O50 OpenHands：模型路由拥有切换状态，运行时可追加路线&quot;">​</a></h3><p>11月19日 #6789/#6835 已合入。RouterLLM 持有自动/手动路由与所选模型状态，支持查询、切换、恢复自动选择，并可在会话中新增 route，必要时把普通 LLM 包成 router。Python/TypeScript 客户端及 REST 路径配套；上游下游手工测试不算本地结果，新增并不等于任意模型间上下文兼容。</p><p>原始证据与状态：<a href="https://github.com/OpenHands/software-agent-sdk/pull/6789" target="_blank" rel="noreferrer">MERGED · 2026-11-19T00:07:42Z</a> · <a href="https://github.com/OpenHands/software-agent-sdk/pull/6835" target="_blank" rel="noreferrer">MERGED · 2026-11-19T00:07:43Z</a></p><p>研究追溯：<a href="#a5">A5</a></p><p><span id="o51"></span></p><h3 id="o51-openhands-完成判断器已合入-但主干还没有调用者" tabindex="-1">O51 OpenHands：完成判断器已合入，但主干还没有调用者 <a class="header-anchor" href="#o51-openhands-完成判断器已合入-但主干还没有调用者" aria-label="Permalink to &quot;O51 OpenHands：完成判断器已合入，但主干还没有调用者&quot;">​</a></h3><p>11月18日 #6962 已合入。命名 resolution_judge LLM profile 回答窄 yes/no 问题，再用代码组合为 resolved、待回答/审阅/决定/检查/未完成/不清楚等状态，有独立超时重试。PR 明确当前 main 尚无调用者，不能报告成产品已自动验收任务。值得作为独立验收机制候选。</p><p>原始证据与状态：<a href="https://github.com/OpenHands/software-agent-sdk/pull/6962" target="_blank" rel="noreferrer">MERGED · 2026-11-18T18:00:48Z</a></p><p>研究追溯：<a href="#a3">A3</a></p><p><span id="o52"></span></p><h3 id="o52-langfuse-预算分用户和-key-默认值与硬上限不同" tabindex="-1">O52 Langfuse：预算分用户和 key，默认值与硬上限不同 <a class="header-anchor" href="#o52-langfuse-预算分用户和-key-默认值与硬上限不同" aria-label="Permalink to &quot;O52 Langfuse：预算分用户和 key，默认值与硬上限不同&quot;">​</a></h3><p>11月18日 #20323/#20377/#20440 已合入。key 与 user 可设日/周/月等预算，默认预算实时回退到每个主体而非复制记录；用户自己的 key 预算可替代默认，管理员要限制个人总额应使用 user 上限。控制面和执行已合入，但预算页面只开 PR preview/staging，不能称生产 UI 全量开放；未本地核验并发超支边界。</p><p>原始证据与状态：<a href="https://github.com/langfuse/langfuse/pull/20323" target="_blank" rel="noreferrer">MERGED · 2026-11-18T10:33:42Z</a> · <a href="https://github.com/langfuse/langfuse/pull/20377" target="_blank" rel="noreferrer">MERGED · 2026-11-18T17:50:52Z</a> · <a href="https://github.com/langfuse/langfuse/pull/20440" target="_blank" rel="noreferrer">MERGED · 2026-11-18T18:59:33Z</a></p><p>研究追溯：<a href="#a5">A5</a></p><p><span id="o53"></span></p><h3 id="o53-langfuse-bedrock-角色连接绑定租户-external-id" tabindex="-1">O53 Langfuse：Bedrock 角色连接绑定租户 external ID <a class="header-anchor" href="#o53-langfuse-bedrock-角色连接绑定租户-external-id" aria-label="Permalink to &quot;O53 Langfuse：Bedrock 角色连接绑定租户 external ID&quot;">​</a></h3><p>11月18日 #20379 已合入。通过跨账号角色使用客户 IAM role，每连接有服务端生成且绑定项目/组织的 external ID，避免 confused-deputy；自托管需配置跨账号角色，公共 API upsert 及未获资格组织仍不接受角色配置。学习价值在凭证与租户绑定，不能简化为所有接入都已免密。</p><p>原始证据与状态：<a href="https://github.com/langfuse/langfuse/pull/20379" target="_blank" rel="noreferrer">MERGED · 2026-11-18T16:57:56Z</a></p><p>研究追溯：<a href="#a2">A2</a> · <a href="#a5">A5</a></p><p><span id="o54"></span></p><h3 id="o54-langfuse-现代-mcp-接入与工具替换语义分别核验" tabindex="-1">O54 Langfuse：现代 MCP 接入与工具替换语义分别核验 <a class="header-anchor" href="#o54-langfuse-现代-mcp-接入与工具替换语义分别核验" aria-label="Permalink to &quot;O54 Langfuse：现代 MCP 接入与工具替换语义分别核验&quot;">​</a></h3><p>11月18日 #20384/#20418 已合入。MCP 按请求是否有 2026 envelope 选择现代或既有路径，并记录协议 era；不强迫旧客户端一起迁移。另修正 updateEvaluator 文案：它是全量替换，省略可选字段会清除，原线上 schema 并未缺字段。值得学习 wire 契约、模型读到的说明与真实写入语义的一致性。</p><p>原始证据与状态：<a href="https://github.com/langfuse/langfuse/pull/20384" target="_blank" rel="noreferrer">MERGED · 2026-11-18T08:48:50Z</a> · <a href="https://github.com/langfuse/langfuse/pull/20418" target="_blank" rel="noreferrer">MERGED · 2026-11-18T09:45:11Z</a></p><p>研究追溯：<a href="#a1">A1</a> · <a href="#a6">A6</a></p><p><span id="o55"></span></p><h3 id="o55-phoenix-评测器本身也要用正反对照检验" tabindex="-1">O55 Phoenix：评测器本身也要用正反对照检验 <a class="header-anchor" href="#o55-phoenix-评测器本身也要用正反对照检验" aria-label="Permalink to &quot;O55 Phoenix：评测器本身也要用正反对照检验&quot;">​</a></h3><p>11月18日 #17821 已合入，21.2.1 次日发行包含这份技能指导。基于上游 Harbor 经历，要求以最终成果定义成功、避免题目泄露评分提示，用 oracle/nop 检查 verifier，并把崩溃、错误答案与评测管线失败分开。文档和示例可复用，不是新 benchmark 成绩或本地实验。</p><p>原始证据与状态：<a href="https://github.com/Arize-ai/phoenix/pull/17821" target="_blank" rel="noreferrer">MERGED · 2026-11-18T21:17:13Z</a> · <a href="https://github.com/Arize-ai/phoenix/releases/tag/arize-phoenix-v21.2.1" target="_blank" rel="noreferrer">RELEASED · 2026-11-19T01:26:55Z</a></p><p>研究追溯：<a href="#a3">A3</a></p><p><span id="o56"></span></p><h3 id="o56-orkas-长命令输出用持续解码器保留中文字符" tabindex="-1">O56 Orkas：长命令输出用持续解码器保留中文字符 <a class="header-anchor" href="#o56-orkas-长命令输出用持续解码器保留中文字符" aria-label="Permalink to &quot;O56 Orkas：长命令输出用持续解码器保留中文字符&quot;">​</a></h3><p>11月18日 #228 已合入。stdout/stderr 每管道使用持续解码器，修复 UTF-8 字符跨事件分块损坏，保留字节统计、输出上限、取消和终态回执。上游测量不是 Windows 本机时延保证；本轮未安装。学习价值中高，适合数字员工中文成果证据链，主雷达不变，MIT 已核验。</p><p>原始证据与状态：<a href="https://github.com/Orkas-AI/Orkas/pull/228" target="_blank" rel="noreferrer">MERGED · 2026-11-18T14:41:55Z</a></p><p>研究追溯：<a href="#a6">A6</a> · <a href="#a7">A7</a></p><p><span id="o57"></span></p><h3 id="o57-adk-移除可视构建助手与内置双下划线-agent-入口" tabindex="-1">O57 ADK：移除可视构建助手与内置双下划线 Agent 入口 <a class="header-anchor" href="#o57-adk-移除可视构建助手与内置双下划线-agent-入口" aria-label="Permalink to &quot;O57 ADK：移除可视构建助手与内置双下划线 Agent 入口&quot;">​</a></h3><p>11月19日提交移除已撤下可视构建器背后的 <strong>adk_agent_builder_assistant、工具及加载机制。</strong> 开头名称改为保留并拒绝，API 返回404，不能再落到用户 Agent 目录。它是主干兼容变化；依赖该开发入口的应用需迁移，不能推成 ADK 整体停止维护。</p><p>原始证据与状态：<a href="https://github.com/google/adk-python/commit/e2a21ac23260d043bf9d217b573af1bef48f0f70" target="_blank" rel="noreferrer">COMMITTED · 2026-11-19T01:04:21Z</a></p><p>研究追溯：<a href="#a6">A6</a></p><h2 id="研究分析" tabindex="-1">研究分析 <a class="header-anchor" href="#研究分析" aria-label="Permalink to &quot;研究分析&quot;">​</a></h2><p><span id="a1"></span></p><h3 id="a1-技能信任应覆盖声明、实际参数、执行控制和行为证据" tabindex="-1">A1 技能信任应覆盖声明、实际参数、执行控制和行为证据 <a class="header-anchor" href="#a1-技能信任应覆盖声明、实际参数、执行控制和行为证据" aria-label="Permalink to &quot;A1 技能信任应覆盖声明、实际参数、执行控制和行为证据&quot;">​</a></h3><p><a href="#o1">O1</a> · <a href="#o2">O2</a> · <a href="#o3">O3</a> · <a href="#o4">O4</a> · <a href="#o5">O5</a> · <a href="#o6">O6</a> · <a href="#o21">O21</a> · <a href="#o22">O22</a> · <a href="#o54">O54</a></p><p>已有证据：Bulbasaur把副作用声明、静态评估、可选行为评测拆成可调用机制；MCP中间件和LangGraph修复说明规则必须到达实际调用路径。边界：正则不证明只读，mock不证明真实技能效果，experimental扩展不保证稳定API。实验候选：先固定Bulbasaur已合入版本，在独立开发环境用允许/超限/未声明副作用案例检查拒绝、回执与精确技能hash；真实执行需另做隔离设计。CodeFlowMu可比较技能准入和动作控制，FCoP只对照工件身份、声明与证据契约，不直接承担所有执行策略。成本是规则映射、沙箱和评测案例；本轮均未运行。分类：实验候选。</p><p>可讨论的技术议题：技能声明与实际动作冲突时，拒绝依据和技能hash能否在同一回执中重建？</p><p><span id="a2"></span></p><h3 id="a2-授权不能从祖先对话、团队默认或凭证存在直接继承" tabindex="-1">A2 授权不能从祖先对话、团队默认或凭证存在直接继承 <a class="header-anchor" href="#a2-授权不能从祖先对话、团队默认或凭证存在直接继承" aria-label="Permalink to &quot;A2 授权不能从祖先对话、团队默认或凭证存在直接继承&quot;">​</a></h3><p><a href="#o11">O11</a> · <a href="#o12">O12</a> · <a href="#o13">O13</a> · <a href="#o14">O14</a> · <a href="#o19">O19</a> · <a href="#o30">O30</a> · <a href="#o31">O31</a> · <a href="#o32">O32</a> · <a href="#o33">O33</a> · <a href="#o35">O35</a> · <a href="#o36">O36</a> · <a href="#o37">O37</a> · <a href="#o43">O43</a> · <a href="#o45">O45</a> · <a href="#o48">O48</a> · <a href="#o53">O53</a></p><p>已有证据：子Agent授权证据、手动调用者、连接安装、租户external ID和手机所见head分别有独立边界；团队默认还受组织策略约束。待验证：CodeFlowMu从岗位委派到工具动作是否保留这些边界，本轮没有本地缺陷证据。实验候选：撤销权限后迟到调用、他人例程Run now、分叉继承历史、手机批准后PR换head，比较当时身份/对象版本/决策和实际副作用。审批追齐证据与裁决后的重核值得重点学习；凭证移出argv仅减少一类暴露。FCoP可比较委派与批准记录关联，账号、凭证、沙箱执行归Runtime/适配层。代价是状态版本、授权查询和失败时人工介入。分类：持续观察及实验候选。</p><p>可讨论的技术议题：执行对象或权限在批准后变化时，宿主是在动作前再次核验，还是仅重放旧批准？</p><p><span id="a3"></span></p><h3 id="a3-数字员工完成要连接实际派发、结果接收、验收与外部交付" tabindex="-1">A3 数字员工完成要连接实际派发、结果接收、验收与外部交付 <a class="header-anchor" href="#a3-数字员工完成要连接实际派发、结果接收、验收与外部交付" aria-label="Permalink to &quot;A3 数字员工完成要连接实际派发、结果接收、验收与外部交付&quot;">​</a></h3><p><a href="#o15">O15</a> · <a href="#o16">O16</a> · <a href="#o23">O23</a> · <a href="#o26">O26</a> · <a href="#o28">O28</a> · <a href="#o38">O38</a> · <a href="#o39">O39</a> · <a href="#o44">O44</a> · <a href="#o46">O46</a> · <a href="#o48">O48</a> · <a href="#o51">O51</a> · <a href="#o55">O55</a></p><p>已有证据：子回复可在父中断时丢失、Agent消息曾看起来像用户、任务完成曾早于PR合入，verifier本身也可能误判。待验证：这些缺口是否存在于本地三岗位交付。本轮优先实验候选：研究→实现→独立验收，注入父中断、迟到子结束、人工拒绝替代工具结果、PR关闭未合入及verifier假阳性，分别检查实际派发、工件hash/ID、消费和独立验收回执。Paperclip的外部事实门槛可与OpenHands窄问题判断器对照，但后者主干尚未接入调用。FCoP比较任务/工件/来源/验收关联，Runtime负责等待、锁和实际调度。成本为故障注入、正反对照及外部状态查询。分类：高价值实验候选。</p><p>可讨论的技术议题：怎样证明复核者确实读取了对应版本成果，而不是只出现一条“已完成”消息？</p><p><span id="a4"></span></p><h3 id="a4-恢复要区分会话存活、turn续接、任务结算和资源释放" tabindex="-1">A4 恢复要区分会话存活、turn续接、任务结算和资源释放 <a class="header-anchor" href="#a4-恢复要区分会话存活、turn续接、任务结算和资源释放" aria-label="Permalink to &quot;A4 恢复要区分会话存活、turn续接、任务结算和资源释放&quot;">​</a></h3><p><a href="#o17">O17</a> · <a href="#o18">O18</a> · <a href="#o20">O20</a> · <a href="#o27">O27</a> · <a href="#o29">O29</a> · <a href="#o34">O34</a> · <a href="#o38">O38</a> · <a href="#o42">O42</a> · <a href="#o47">O47</a> · <a href="#o49">O49</a></p><p>已有证据：磁盘预留不保证turn续接，终态运行仍可能在结算，HTTP200不保证合法控制响应，调用超时也不保证worker已停。实验候选：沿昨日恢复议题增加满盘后同会话续接、用量等待时扫锁、空闲worker死亡和锁等待风暴；观察重复副作用、丢失回执、资源泄漏与人工等待。对于迁移，保留“部分写入、未回滚”的明确状态。FCoP比较可恢复状态与证据，线程池、租约、磁盘、重试和资源回收归Runtime。成本是受控故障注入及可靠外部动作桩；无本地运行结果。分类：实验候选及恢复资料留存。</p><p>可讨论的技术议题：超时、停止或终态出现后，用什么独立证据确认执行器和资源真的已经结束？</p><p><span id="a5"></span></p><h3 id="a5-长期记忆与成本治理都要核对生命周期和主体" tabindex="-1">A5 长期记忆与成本治理都要核对生命周期和主体 <a class="header-anchor" href="#a5-长期记忆与成本治理都要核对生命周期和主体" aria-label="Permalink to &quot;A5 长期记忆与成本治理都要核对生命周期和主体&quot;">​</a></h3><p><a href="#o24">O24</a> · <a href="#o25">O25</a> · <a href="#o26">O26</a> · <a href="#o29">O29</a> · <a href="#o42">O42</a> · <a href="#o50">O50</a> · <a href="#o52">O52</a> · <a href="#o53">O53</a></p><p>已有证据：CrewAI默认库退出即删、共享默认ID曾混合运行、模型连接可误复用已关闭事件循环、用户key默认预算可被自己的具体预算替代。它们说明配置名本身不足以证明持久化、隔离或硬预算。体验候选：备份旧Chroma数据后对照重启/双进程/显式续跑与不同用户key预算，核验主体与持久化，不直接迁移生产数据。CodeFlowMu岗位长期记忆、用户成本和模型路由值得分别比对；FCoP不直接承担向量库或网关计费。代价是重嵌入、存储部署、连接数量及模型费用。分类：体验候选；本轮未升级安装。</p><p>可讨论的技术议题：默认预算和固定本地路径，在多员工、多进程和用户可自行配置时究竟形成什么约束？</p><p><span id="a6"></span></p><h3 id="a6-协议研究-消息、工件、外部事件和执行身份分层比较" tabindex="-1">A6 协议研究：消息、工件、外部事件和执行身份分层比较 <a class="header-anchor" href="#a6-协议研究-消息、工件、外部事件和执行身份分层比较" aria-label="Permalink to &quot;A6 协议研究：消息、工件、外部事件和执行身份分层比较&quot;">​</a></h3><p><a href="#o4">O4</a> · <a href="#o5">O5</a> · <a href="#o6">O6</a> · <a href="#o7">O7</a> · <a href="#o8">O8</a> · <a href="#o22">O22</a> · <a href="#o40">O40</a> · <a href="#o44">O44</a> · <a href="#o46">O46</a> · <a href="#o54">O54</a> · <a href="#o56">O56</a> · <a href="#o57">O57</a></p><p>已有证据：MCP扩展管理接入请求，GitHub工件API有仓库rollout，CLI事件流提供等待入口，Orca把普通邮件与改变Dispatch的消息分开并协商版本；这些不在同一层。与FCoP的比较应逐项看任务/消息/工件标识、状态权威、版本与证据契约，而非统称协议竞品。实验候选：离线重放消息乱序、重复、旧版本能力、变更后的工件ID与UTF-8分块；另在获得预览资格后试CLI等待。exactly-once、断线补漏和不同宿主端到端互通尚未核验。代价是适配状态持久化、补偿和版本兼容。分类：互补协议资料及实验候选。</p><p>可讨论的技术议题：跨主机邮件能送达之后，谁有权改变任务状态，旧宿主如何明确拒绝不支持的动作？</p><p><span id="a7"></span></p><h3 id="a7-竞品体验先验收机制-再判断整体产品成熟度" tabindex="-1">A7 竞品体验先验收机制，再判断整体产品成熟度 <a class="header-anchor" href="#a7-竞品体验先验收机制-再判断整体产品成熟度" aria-label="Permalink to &quot;A7 竞品体验先验收机制，再判断整体产品成熟度&quot;">​</a></h3><p><a href="#o9">O9</a> · <a href="#o10">O10</a> · <a href="#o18">O18</a> · <a href="#o25">O25</a> · <a href="#o28">O28</a> · <a href="#o29">O29</a> · <a href="#o30">O30</a> · <a href="#o32">O32</a> · <a href="#o34">O34</a> · <a href="#o35">O35</a> · <a href="#o36">O36</a> · <a href="#o37">O37</a> · <a href="#o38">O38</a> · <a href="#o39">O39</a> · <a href="#o40">O40</a> · <a href="#o41">O41</a> · <a href="#o42">O42</a> · <a href="#o43">O43</a> · <a href="#o44">O44</a> · <a href="#o45">O45</a> · <a href="#o46">O46</a> · <a href="#o47">O47</a> · <a href="#o56">O56</a></p><p>本轮判断：Bulbasaur是技能准入/评测实验优先候选（Apache-2.0）；Paperclip是交付门槛与恢复优先候选（MIT），需要固定含目标修复的版本，不能把稳定版发布后的合入当已打包。Orca的移动批准、跨宿主边界与协作状态学习价值高、竞争关注提高，仍属第二圈；根LICENSE读取失败，体验前许可待补。Beads与Orkas根MIT已核验，分别适合任务工件/迁移和中文长输出对照。Copilot团队能力分发与连接器准入提高企业产品关注，但计划、策略和预览资格有限制。主/第二圈名单均不改，单项修复不证明整体成熟。安装、手机/Windows验收、签名/回滚及完整商业边界本轮均未实际验证。分类：按前述次序体验候选，不生成开发派工。</p><p>可讨论的技术议题：正式版本、源码合入、实验开关和实际可用的企业交付，能否逐项给出同一版本的验收证据？</p><h2 id="跨项目共振、分类与双源核查" tabindex="-1">跨项目共振、分类与双源核查 <a class="header-anchor" href="#跨项目共振、分类与双源核查" aria-label="Permalink to &quot;跨项目共振、分类与双源核查&quot;">​</a></h2><p>A1/A3/A4优先保留为实验候选，A2为授权边界对照，A5为升级与长期运行体验候选，A6为互补协议资料及实验候选，A7为竞品体验顺序。以上均未执行，不能当成本地缺陷、已验证机制、文章或开发派工。互动仅保留技术议题，未对外评论。</p><p>GitHub按原始仓库检查commit、Issues/PR与Release，并补读历史发行及部分Issue分页、入选PR、技能/API文档和部分License。264个来源/类型核查项中229个完整、32个仍有分页缺口、TSA三个接口无法访问；只有完整项推进相应基线，旧缺口保留。原 superset-sh/superset 返回迁移，已核对同一仓库ID 1080370450对应 ParadevAI/Paradev，并跟随检查；没有改名或替换Registry，迁移源历史分页仍不完整。Codex Release大页请求失败后小页成功，仍保留未完成分页。</p><p>第二类来源实际核查Cursor changelog、MCP官方博客、GitHub changelog和三篇11月18日官方公告；Cursor/MCP博客当前最新条目仍为11月6日/11日，未算新增。五位作者主页扩展批次长时间未返回，已中止，记未完成，不推进基线；没有穷尽47人的X、回复、论文页、Discussion与所有安装/架构/商业边界。Bulbasaur Apache-2.0及Paperclip/Beads/Orkas根MIT已核验；Orca根LICENSE读取失败，适用许可待补。人物与仓库保持多对多关系，Mansura关联项目不是AGENTSAFE官方Artifact，中文名始终为赵越。</p><p>新发行仅按交付状态计增量，历史合入和旧开放PR不冒充当日新增；CrewAI #9324仅用于解释本次发行边界。未覆盖完整生产路径的上游测试不能替代本地验证。日报仅更新中英文当日源文件与两个索引，不改research/runtime/**、业务生命周期、入口组件和布局；网站发布结果以独立回执及聊天为准。</p><h2 id="跨日未结算研究-11-月-17-日-a2-与-a4" tabindex="-1">跨日未结算研究：11 月 17 日 A2 与 A4 <a class="header-anchor" href="#跨日未结算研究-11-月-17-日-a2-与-a4" aria-label="Permalink to &quot;跨日未结算研究：11 月 17 日 A2 与 A4&quot;">​</a></h2><p><a href="./2026-11-17#11-月-17-日研究续报">11 月 17 日续报</a>留下的 A2（Stop／超时后的副作用结算）与 A4（完整父子结果消费、独立验收）截至本日仍未完成。11 月 18、19 日日报的 A2／A4 是各自当天重新编号的分析，不能据此认定旧实验已经补做。</p><p>补做顺序是先验证停止发生于 dispatch 前、dispatch 后和回执丢失时的真实副作用及恢复判定，再验证多个子结果进入正确父任务、正确工件版本并由独立验收者处理。每项应另存固定版本、输入、断言和结果；没有运行证据前保持“待实验”，也不据此产出精品文章或 CodeFlowMu 开发评审。</p>',333)])])}const f=e(t,[["render",l]]);export{u as __pageData,f as default};
